64	impl RecurrentState {
65	    /// Allocate zeroed recurrent state for all linear attention layers.
66	    pub(crate) fn new(
67	        ctx: &DeviceContext,
68	        config: &Config35,
69	        geometry: LocalGeometry,
70	    ) -> Result<Self> {
71	        let (num_linear_layers, state_size, conv_state_size) = per_layer_dims(config, geometry);
72	
73	        let mut layers = Vec::with_capacity(num_linear_layers);
74	        for _ in 0..num_linear_layers {
75	            let state: CudaSlice<f32> = ctx
76	                .stream
77	                .alloc_zeros(state_size)
78	                .map_err(|e| anyhow::anyhow!("Alloc recurrent state failed: {}", e))?;
79	            layers.push(LayerRecurrentState {
80	                state,
81	                conv_state: DeviceVec::zeros(ctx, conv_state_size)?,
82	            });
83	        }
84	
85	        Ok(Self { layers, seq_len: 0 })
86	    }
